/**
 * Development Recipe Image Audit Tool
 * Validates 1-to-1 canonical recipe image mapping, detecting:
 * - Missing or empty image_url
 * - Duplicated image_urls across recipes
 * - Unintentional placeholder usage
 * - Invalid protocols/paths
 */
function auditRecipesData(dataset) {
    const list = dataset || (typeof INITIAL_RECIPES !== 'undefined' ? INITIAL_RECIPES : []);
    const results = {
        total: list.length,
        valid: 0,
        missing: [],
        duplicates: {},
        placeholders: [],
        invalidPaths: [],
        sriLankan: {
            count: 0,
            expected: 10,
            recipes: [],
            duplicates: [],
            missingImages: [],
            brokenPaths: []
        }
    };

    const urlMap = new Map();
    const slImgSet = new Set();

    list.forEach(recipe => {
        const isSL = (recipe.category || '').toLowerCase() === 'sri lankan';
        if (isSL) {
            results.sriLankan.count++;
            const filename = (recipe.image_url || '').split('/').pop();
            if (slImgSet.has(recipe.image_url)) {
                results.sriLankan.duplicates.push({ id: recipe.id, title: recipe.title, image_url: recipe.image_url });
            }
            slImgSet.add(recipe.image_url);

            if (!recipe.image_url || recipe.image_url.includes('placeholder')) {
                results.sriLankan.missingImages.push({ id: recipe.id, title: recipe.title });
            }

            results.sriLankan.recipes.push({
                id: recipe.id,
                title: recipe.title,
                category: recipe.category,
                image_url: recipe.image_url,
                image_filename: filename
            });
        }

        if (!recipe.image_url || typeof recipe.image_url !== 'string' || recipe.image_url.trim() === '') {
            results.missing.push({ id: recipe.id, title: recipe.title });
            return;
        }

        const url = recipe.image_url.trim();

        if (url.includes('recipe-placeholder.jpg')) {
            results.placeholders.push({ id: recipe.id, title: recipe.title });
        }

        if (!url.startsWith('http://') && !url.startsWith('https://') && !url.startsWith('assets/')) {
            results.invalidPaths.push({ id: recipe.id, title: recipe.title, image_url: url });
        }

        if (urlMap.has(url)) {
            const existing = urlMap.get(url);
            if (!results.duplicates[url]) {
                results.duplicates[url] = [existing];
            }
            results.duplicates[url].push({ id: recipe.id, title: recipe.title });
        } else {
            urlMap.set(url, { id: recipe.id, title: recipe.title });
        }

        results.valid++;
    });

    const duplicateCount = Object.keys(results.duplicates).length;
    return {
        ...results,
        duplicateCount,
        isClean: results.missing.length === 0 && duplicateCount === 0 && results.invalidPaths.length === 0,
        sriLankanValid: results.sriLankan.count === 10 && results.sriLankan.duplicates.length === 0 && results.sriLankan.missingImages.length === 0
    };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { INITIAL_RECIPES, auditRecipesData };
}

